def transform(grid):
    out=[r[:] for r in grid]
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==8]
    if len(set(r for r,c in pts))==1:
        out[0]=[8]*len(out[0])
    else:
        for row in out: row[0]=8
    return out

